INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8429, 'ពង្រាត \((x+2y)^{3}\) ៖', NULL, '["\\(x^{3} + 6 x^{2} y + 6 x y^{2} + 8 y^{3}\\)", "\\(x^{3} + 6 x^{2} y + 12 x y^{2} + 8 y^{3}\\)", "\\(x^{3} + 6 x^{2} y + 12 x y^{2} + 2 y^{3}\\)", "\\(x^{3} + 8 y^{3}\\)"]', 1, NULL, 3, 'mcq', '\((x+2y)^{3} = x^{3} + 6 x^{2} y + 12 x y^{2} + 8 y^{3}\)។', 'កន្សោមពីជគណិត', 'hard', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8430, 'គណនា \(\dfrac{6x^{2}+5x-4}{2x-1}\) ៖', NULL, '["\\(3 x - 4\\)", "\\(3 x + 4\\)", "\\(3 x + 2\\)", "\\(3 x + 1\\)"]', 1, NULL, 3, 'mcq', '\(\dfrac{6x^{2}+5x-4}{2x-1} = 3 x + 4\)។', 'កន្សោមពីជគណិត', 'hard', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8431, 'ដាក់ជាផលគុណកត្តា \(x^{3}-2x^{2}-4x+8\) ៖', NULL, '["\\(\\left(x - 2\\right) \\left(x + 2\\right)\\)", "\\(\\left(x - 2\\right)^{2} \\left(x + 2\\right)\\)", "\\(\\left(x - 2\\right) \\left(x + 2\\right)^{2}\\)", "\\(\\left(x - 2\\right) \\left(x^{2} + 4\\right)\\)"]', 1, NULL, 3, 'mcq', '\(x^{3}-2x^{2}-4x+8 = \left(x - 2\right)^{2} \left(x + 2\right)\)។', 'កន្សោមពីជគណិត', 'hard', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8432, 'គូបមួយមានទ្រនុងប្រវែង \(2a\)។ ផ្ទៃក្រឡានៃមុខមួយគឺ៖', 'g8-3243494bb4.svg', '["\\(4a\\)", "\\(4a^2\\)", "\\(2a^2\\)", "\\(8a^2\\)"]', 1, NULL, 3, 'mcq', '\((2a)^2 = 4a^2\)។', 'កន្សោមពីជគណិត', 'pisa', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8433, 'គូបមួយមានទ្រនុងប្រវែង \(2a\)។ មាឌនៃគូបគឺ៖', 'g8-3243494bb4.svg', '["\\(8a^3\\)", "\\(4a^3\\)", "\\(6a^3\\)", "\\(8a\\)"]', 0, NULL, 3, 'mcq', '\((2a)^3 = 8a^3\)។', 'កន្សោមពីជគណិត', 'pisa', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8434, 'សួនច្បារចតុកោណកែងមានបណ្តោយ \(5x\) និងទទឹង \(2x\)។ ផ្ទៃក្រឡា \(\mathcal{A}\) គឺ៖', 'g8-6c2427f5fa.svg', '["\\(7x^2\\)", "\\(10x\\)", "\\(10x^2\\)", "\\(7x\\)"]', 2, NULL, 3, 'mcq', '\((5x)(2x) = 10x^2\)។', 'កន្សោមពីជគណិត', 'pisa', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8435, 'រូបថតមួយមានរាងចតុកោណកែងវិមាត្រ \(3x+2\) និង \(x+1\) (ម៉ែត្រ)។ ផ្ទៃក្រឡាគឺ៖', 'g8-87d701baf5.svg', '["\\(4x + 3\\)", "\\(3x^2 + 2\\)", "\\(3x^2 + 5x + 3\\)", "\\(3x^2 + 5x + 2\\)"]', 3, NULL, 3, 'mcq', '\((3x+2)(x+1) = 3x^2 + 3x + 2x + 2\)។', 'កន្សោមពីជគណិត', 'pisa', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8436, 'ផ្លូវជុំវិញផ្ទះមានវិមាត្រ \(18a\) និង \(12a\)។ ផ្ទៃក្រឡាផ្លូវគឺ៖', 'g8-91e67ec021.svg', '["\\(216a^2\\)", "\\(216a\\)", "\\(30a\\)", "\\(30a^2\\)"]', 0, NULL, 3, 'mcq', '\((18a)(12a) = 216a^2\)។', 'កន្សោមពីជគណិត', 'pisa', 1, '8', 'កន្សោមពីជគណិត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8437, 'ក. ប្រាប់មេគុណ អថេរ និងដឺក្រេនៃ \(-\dfrac{3}{4}ab^2x\) និង \(8x^3yz^2\)។ ខ. ក្នុង \(\dfrac{1}{2}xy,\ -2x^2y,\ ay,\ 3ax,\ 2xy^2,\ xy\) រកឯកធាដូចគ្នា។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(-\dfrac{3}{4}ab^2x\) ៖ មេគុណ \(-\dfrac{3}{4}\) អថេរ \(a, b, x\) ដឺក្រេ \(1+2+1 = 4\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8438, 'គណនា ក. \((2x^{2}+3x+1)+(-x^{2}+2x+4)\) ខ. \((2x^{2}+3x+1)-(-x^{2}+2x+4)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ដុំឯកធាដូចគ្នា \((2x^{2}+3x+1)+(-x^{2}+2x+4)\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8439, 'គណនាផលគុណ ក. \(2x^2(2x^2 + 3x - 1)\) ខ. \((a^2 + 2ab)(a - b)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(2x^2 \cdot 2x^2 + 2x^2 \cdot 3x - 2x^2 \cdot 1\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8440, 'ពង្រាត ក. \((5x + 2y)^2\) ខ. \((x - 4y)^2\) គ. \((x - 2)(x + 2)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((5x)^2 + 2(5x)(2y) + (2y)^2 = 25x^2 + 20xy + 4y^2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8441, 'គណនា ក. \((12a^{2}+2ab+54)+(9a^{2}-4ab-25)\) ខ. \((12a^{2}+2ab+54)-(9a^{2}-4ab-25)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ដុំឯកធាដូចគ្នា \((12a^{2}+2ab+54)+(9a^{2}-4ab-25)\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8442, 'ធ្វើវិធីចែក \((6x^2 + 5x - 4) \div (2x - 1)\) និង \((x^2 - 2x + 4) \div (x - 1)\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(6x^2 \div 2x = 3x\) ; \(3x(2x-1) = 6x^2 - 3x\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8443, 'ដាក់ជាផលគុណកត្តា ក. \(x^3 - 2x^2 - 4x + 8\) ខ. \(4x^2 + y^2 - b^2 - 4xy\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((x^3 - 2x^2) - (4x - 8) = x^2(x - 2) - 4(x - 2)\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8444, 'បង្ហាញថា ក. \((1+x)(1-x)(1+x^2) = 1 - x^4\) ខ. \(5b^2 - 3(b+1)(b-1) = 2b^2 + 3\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((1+x)(1-x) = 1 - x^2\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8445, 'ដាក់ជាផលគុណកត្តា ក. \(8x^3 + y^3\) ខ. \(27y^3 - 64\) គ. \(3x^2 + 14x + 8\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \((2x)^3 + y^3 = (2x + y)(4x^2 - 2xy + y^2)\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8446, 'គូបមួយមានទ្រនុងប្រវែង \(2a\)។ ក. គណនាផ្ទៃក្រឡានៃមុខមួយ។ ខ. គណនាផ្ទៃក្រឡាសរុបនៃគូប។ គ. គណនាមាឌនៃគូប។', 'g8-3243494bb4.svg', '[]', 0, NULL, 5, 'writing', 'ក. \((2a)^2 = 4a^2\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8447, 'រូបថតមួយរាងចតុកោណកែងមានវិមាត្រ \(3x + 2\) និង \(x + 1\) ម៉ែត្រ។ ក. គណនាផ្ទៃក្រឡារូបថត។ ខ. គណនាបរិមាត្ររូបថត។ គ. គណនាផ្ទៃក្រឡា ពេល \(x = 2\)។', 'g8-46df87b0fc.svg', '[]', 0, NULL, 5, 'writing', 'ក. \((3x+2)(x+1) = 3x^2 + 3x + 2x + 2 = 3x^2 + 5x + 2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8448, 'ស្រះទឹករាងចតុកោណកែងមានផ្ទៃក្រឡា \(16xy^2\) ទទឹង \(4y\)។ ក. គណនាបណ្តោយ។ ខ. គណនាបរិមាត្រ។ គ. គណនាបណ្តោយ និងទទឹង ពេល \(x = 3, y = 2\)។', 'g8-5439fe41f4.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(\dfrac{16xy^2}{4y} = 4xy\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8449, 'ផ្លូវដើរជុំវិញផ្ទះមានវិមាត្រ \(18a\) និង \(12a\)។ ក. គណនាផ្ទៃក្រឡាផ្លូវ។ ខ. គណនាបរិមាត្រផ្លូវ។ គ. បើ \(a = 2\ \text{m}\) គណនាផ្ទៃក្រឡា។', 'g8-91e67ec021.svg', '[]', 0, NULL, 5, 'writing', 'ក. \((18a)(12a) = 216a^2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 8450, 'ត្រីកោណ \(ABC\) មានជ្រុង \(AB = 2x\), \(BC = 3y\), \(CA = 8\)។ ក. សរសេរបរិមាត្រជាពហុធា។ ខ. ប្រាប់ដឺក្រេនិងចំនួនតួ។ គ. គណនាបរិមាត្រ ពេល \(x = 4, y = 2\)។', 'g8-8eb2e28d29.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(P = 2x + 3y + 8\) (1 ពិន្ទុ)
